var LEARN_QA = [{"s": "幼升小", "q": "要不要提前教拼音和算术？", "a": "不建议系统性提前教学。多数小学实行「零起点教学」，抢跑优势通常在两个月内消失，反而容易让孩子开学后注意力下降。更值得投入的是「上学能力」：作息、握笔、表达需求、整理书包。", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "指标到校和择校怎么权衡？", "a": "先并排看两条路径：指标到校看「学籍连续性 + 校内表现」，择校看目标校招生范围与通勤成本。建议用「升学路径地图」把时间轴并排拉直，再对照孩子实际学籍做选择——不要问「哪个更好」，要问「哪个更适合我家」。", "by": "教育顾问 · 示范"}, {"s": "初升高", "q": "孩子成绩中等，路径怎么规划？", "a": "中等成绩段其实是路径最丰富的区间：普高统招、指标到校（若资格在）、民办、中职职教高考、艺体特长都可以纳入备选。建议逐条核对资格条件，再定主攻方向与保底方案。", "by": "教育顾问 · 示范"}, {"s": "高考", "q": "志愿「冲稳保」怎么分配？", "a": "常见做法是冲 2–3 个、稳 3–4 个、保 1–2 个，具体数量看批次规则与家庭风险承受度。先用「位次换算」做线差参考，正式填报以当年一分一段表为准。", "by": "教育顾问 · 示范"}, {"s": "家长心理", "q": "大考前，家长怎么说话不添乱？", "a": "少问「考得怎么样」，多问「今天想吃什么」。把焦虑留在自己这里，把稳定交给孩子。一句示范话术：「不管结果如何，我们都在。」", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "民办摇号没中，是不是就没学上了？", "a": "不是。公民同招下，未摇中的由公办统筹安排；关键是提前把公办对口路径的材料（户籍 / 居住等）逐项核对到位，别把全部筹码押在摇号上。", "by": "教育顾问 · 示范"}, {"s": "初升高", "q": "住校还是走读，怎么决定？", "a": "先算三笔账：单程通勤时间（超过 40 分钟要认真权衡）、孩子自理与作息习惯、家庭陪伴需求。可以先用一个月「试住期」再定；无论哪种，保持固定的沟通节奏。", "by": "教育顾问 · 示范"}, {"s": "高考", "q": "强基计划值得报吗？", "a": "强基适合「基础学科意向明确 + 能接受本硕博衔接培养」的孩子；它锁定的是一条长线路径，不适合「先占坑再说」。建议对照孩子真实的学科兴趣，再做决定。", "by": "教育顾问 · 示范"}, {"s": "幼升小", "q": "公立和私立幼儿园，幼升小衔接有差别吗？", "a": "小学零起点教学下，差别主要在习惯而非知识。重点是作息规律、能坐住 20 分钟、表达清楚需求；这些在家也能练。选择时更该看距离与接送可行性。", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "奥数还值得学吗？", "a": "如果目标是经批准的少数理科特色活动，系统奥数是基础；但对大多数孩子，把校内数学吃透 + 培养阅读理解更划算。学奥数前先问孩子愿不愿意，再问为什么学。", "by": "教育顾问 · 示范"}, {"s": "家长心理", "q": "家里老人育儿观念不一致，怎么破？", "a": "开家庭会议定「底线清单」：写明 3–5 条不可妥协项（如作息、屏幕时间），其余放手。父母是教育决策人，祖辈是执行伙伴——角色先分清，矛盾少一半。", "by": "教育顾问 · 示范"}];
var LEARN_TIPS = [{"s": "初升高", "q": "陪考三年，我做对了三件事", "a": "一是初一就建「重要节点台账」，每条政策都记文号与日期；二是不拿孩子和别人比，只和上周的他比；三是每次大考后开 20 分钟家庭复盘会：只谈事实，不谈情绪。", "by": "2026 届家长 · 示范"}, {"s": "初升高", "q": "志愿填报：我们家做了三次模拟", "a": "一模后粗排、政策公布后细排、正式填报前只微调。三次模拟让我们提前发现了两处明显失误（保底校梯度不够、通勤没算往返），正式填报时只花了半小时。", "by": "2025 届家长 · 示范"}, {"s": "陪读生活", "q": "租房陪读一年：成本清单与踩坑", "a": "省下的通勤时间约 40 分钟/天，但搬家成本、换租溢价、大人通勤变长都是真实成本。建议先短租两个月试住，再决定要不要长租；合同里把「续租涨幅」写清楚。", "by": "陪读家长 · 示范"}, {"s": "家长心理", "q": "从焦虑到放手：我把家长群取消了置顶", "a": "信息要看，但不必随时在线被带着跑。每天固定 20 分钟看整理好的平台信息就够了；剩下的时间还给自己和家人——家长情绪稳，孩子才稳。", "by": "2024 届家长 · 示范"}, {"s": "小升初", "q": "对口材料核对，我们家提前一年就开始了", "a": "把户籍、房产、居住证明按区教委清单逐项核对，缺什么补什么；每年细则有微调，我们的习惯是「发布当天必读原文」。提前一年准备，临门不慌。", "by": "2026 届家长 · 示范"}, {"s": "初升高", "q": "体育中考：我们从初一就开始「攒分」", "a": "平时体育课和过程性评价的分数，靠突击拿不到。我们从初一就固定每周三次户外运动，既是锻炼也是给大脑放空；到最后统一测试反而是最不用担心的一项。", "by": "2025 届家长 · 示范"}, {"s": "陪读生活", "q": "全家搬到学校隔壁，我们后悔了吗？", "a": "换房半年后复盘：通勤省下 1.5 小时/天是真，但离开了熟悉的玩伴圈也是真。建议先试住再卖房；孩子的社交连续性值得单独评估。", "by": "2024 届家长 · 示范"}, {"s": "家长心理", "q": "我把「别人家孩子」从家里请出去了", "a": "有次脱口而出「你看人家谁谁」，孩子回了一句「那你怎么不看看别人家爸妈」。从那天起我们家只做纵向比较——和他自己上个月比。", "by": "2025 届家长 · 示范"}, {"s": "幼升小", "q": "报名前两个月，我们做对了四件小事", "a": "提前在渝快办做完实名认证；接种查验证明去社区医院开了原件；户口本 updating——孩子户口随迁那次迁移要确认已生效；最后把三份材料各扫一份 PDF 存手机。报名当天 10 分钟搞定。", "by": "2026 届家长 · 示范"}, {"s": "高考", "q": "高三一年，家长只做三件事", "a": "管饭、管信息、管情绪。饭是营养也是仪式感；信息是我负责筛——政策原文自己读，只把「与孩子有关的一页」讲给他听；情绪是每天 20 分钟散步，只听不评判。高考是孩子的战场，家长是后勤。", "by": "2025 届家长 · 示范"}, {"s": "全阶段通用", "q": "家长群信息太多？我的「三分钟过滤法」", "a": "群里消息分三类：官方通知（立刻看）、他人情绪（不必看）、广告引流（直接退）。养成习惯后每天花在家长群的时间从 2 小时降到 10 分钟，重点一条没漏。", "by": "自律家长 · 示范"}, {"s": "陪读生活", "q": "给陪读家长的 5 条「少花钱」清单", "a": "①学校食堂比外卖便宜且安全；②二手教材教辅家长群半价；③公交卡学生卡每月省 100+；④自习室不如学校晚自习；⑤警惕「保分班」——最贵的往往是最没用的。", "by": "精打细算家长 · 示范"}];

